-- T-116: deduplicate cache then enforce one row per duplicate name.\nDELETE r1 FROM {{prefix}}vod_repeat r1 JOIN {{prefix}}vod_repeat r2 ON r1.name1=r2.name1 AND r1.id1>r2.id1;\nALTER TABLE {{prefix}}vod_repeat DROP INDEX name1;\nALTER TABLE {{prefix}}vod_repeat ADD UNIQUE KEY uk_vod_repeat_name1 (name1(100));\n